git ls-remote --heads origin 2>&1 | head -20; echo "--- config ---"; ls -la ~/.claude.json 2>/dev/null && python3 -c "
import json,os
p=os.path.expanduser('~/.claude.json')
d=json.load(open(p))
def walk(o,pre=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if 'plugin' in k.lower() or 'marketplace' in k.lower():
                print(pre+k, '=', json.dumps(v)[:400])
            else:
                walk(v,pre+k+'.')
walk(d)
" 2>&1 | head -40

